// A swconfig router's main network and internet line, as the app compiles
// them, against OpenWrt's own default for the same board: what its
// config_generate makes of the board.json (recorded on 25.12.5 as
// boards/<name>.config_generate.txt; the board.json itself generated by
// OpenWrt's ucidef_add_switch from each board's board.d line, see its _note).
// A real switch is not in Docker: what this checks is that the app lays the
// switch out as OpenWrt does, so a router's ports are where it expects.
import test from "ava";
import { readFileSync } from "fs";
import { join } from "path";
import { getOpenWrtState } from "../../engine/getOpenWrtState";
import { parseDeviceFacts } from "../../facts/board";
import { compileIntent } from "../../intent/compile";
import { sampleIntent } from "../helpers/fixtures";

const boards = join(__dirname, "../helpers/boards");
const read = (file: string) => readFileSync(join(boards, file), "utf8");

/** OpenWrt's default from `uci show network`: each switch VLAN's ports, and each interface's or bridge's device. */
const openWrtDefault = (name: string) => {
  const lines = read(`${name}.config_generate.txt`).trim().split("\n");
  const value = (key: string) => lines.find((l) => l.startsWith(`${key}=`))?.split("=")[1].replace(/^'|'$/g, "");
  const vlans = Object.fromEntries(
    [0, 1, 2, 3].flatMap((i) => {
      const vlan = value(`network.@switch_vlan[${i}].vlan`);
      return vlan ? [[vlan, value(`network.@switch_vlan[${i}].ports`)!]] : [];
    })
  );
  return { vlans, wan: value("network.wan.device"), lanBridge: value("network.@device[0].ports") };
};

/** Ports as a set: "1 2 3 4 6t" and "6t 4 3 2 1" are the same VLAN. */
const portSet = (ports: string) => ports.split(" ").filter(Boolean).sort().join(" ");

const compiled = (name: string) => {
  const schema = parseDeviceFacts({ board: JSON.parse(read(`${name}.board.json`)), system: JSON.parse(read(`${name}.system.json`)) });
  const intent = sampleIntent();
  // OpenWrt's default has the main network only: so has this router.
  intent.networks = intent.networks.filter((n) => !n.vlan || n.vlan === 1);
  const plan = compileIntent(intent);
  const router = plan.devices.find((d) => d.tags?.role === "router")!;
  const network = getOpenWrtState({ plan, deviceConfig: router, deviceSchema: { ...schema, version: "25.12.5" } }).config.network!;
  const vlans = Object.fromEntries((network.switch_vlan ?? []).map((v) => [String(v.vlan), String(v.ports)]));
  const wan = (network.interface ?? []).find((i) => i[".name"] === "wan")!.device;
  const lanBridge = (network.device ?? []).find((d) => d.type === "bridge" && String(d.name).startsWith("br-lan"));
  return { vlans, wan, lanBridgePorts: [lanBridge?.ports].flat() };
};

for (const name of ["swconfig-archer-c50", "swconfig-wan-nic"]) {
  test(`${name}: the main network and the internet line sit on the switch as OpenWrt lays them out`, (t) => {
    const openWrt = openWrtDefault(name);
    const ours = compiled(name);
    t.is(portSet(ours.vlans["1"]), portSet(openWrt.vlans["1"]), "the main network: VLAN 1 on the same ports, the CPU tagged");
    t.true(ours.lanBridgePorts.includes(openWrt.lanBridge ?? "(none)"), `the LAN bridge carries ${openWrt.lanBridge}`);
    t.is(String(ours.wan), openWrt.wan ?? "(none)", "the internet line on the same device");
    // Where OpenWrt gives the line a switch VLAN, it is the same ports.
    const wanVlan = /\.(\d+)$/.exec(String(openWrt.wan))?.[1];
    if (wanVlan) t.is(portSet(ours.vlans[wanVlan]), portSet(openWrt.vlans[wanVlan]), "the line's VLAN on the same ports");
  });
}
